/** @brief The fixed corpus fits a uint32_t count. */
uint32_t aicases_count (void)
{
    return (uint32_t)(sizeof(g_rows) / sizeof(g_rows[0]));
}

/** @brief Preserve immutable flash data; never dereference a bad index. */
uint32_t const * aicases_get (uint32_t index, int32_t * p_expected)
{
    if ((NULL == p_expected) || (index >= aicases_count()))
    {
        return NULL;
    }
    *p_expected = g_rows[index].expected;
    return g_rows[index].features;
}

